import{_ as a,o as d,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"قانون حماية المستهلك","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0042-消费者保护法.md","filePath":"ar/0042-消费者保护法.md"}'),e={name:"ar/0042-消费者保护法.md"};function i(o,t,h,n,s,b){return d(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="قانون-حماية-المستهلك" tabindex="-1">قانون حماية المستهلك <a class="header-anchor" href="#قانون-حماية-المستهلك" aria-label="Permalink to &quot;قانون حماية المستهلك&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>42</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>حقوق المستهلك، التجارة العادلة، مناهضة الاحتيال، مسؤولية المنتج، السوق التكافلي</td></tr></tbody></table><h2 id="أولاً-الغرض-التشريعي-ونطاق-التطبيق" tabindex="-1">أولاً: الغرض التشريعي ونطاق التطبيق <a class="header-anchor" href="#أولاً-الغرض-التشريعي-ونطاق-التطبيق" aria-label="Permalink to &quot;أولاً: الغرض التشريعي ونطاق التطبيق&quot;">​</a></h2><p><em>قانون حماية المستهلك</em> أحد القوانين المحورية في النظام القانوني لحضارة التكافل المرساة، ويشكل مع <em>قانون العمل التكافلي</em> الركيزتين الأساسيتين للحياة الاقتصادية. يهدف هذا القانون إلى حماية الحقوق والمصالح المشروعة لجميع المستهلكين داخل كون هنغ يوان، وتنظيم سلوك المعاملات السوقية، والحفاظ على نظام سوقي عادل وصادق وتكافلي، ومنع الممارسات التجارية الافتراسية من التعدي على حقوق ومصالح الكائنات.</p><p>يسري هذا القانون على جميع المستهلكين داخل كون هنغ يوان الذين يشترون أو يستخدمون سلعاً أو يتلقون خدمات لتلبية احتياجات الحياة الشخصية أو العائلية، وكذلك على المشغلين الذين يقدمون السلع أو الخدمات للمستهلكين. كما تسري أحكام هذا القانون على المعاملات عبر الأبعاد، مع إمكانية وضع قواعد تنفيذية وفقاً لاختلافات الأبعاد.</p><h2 id="ثانياً-الحقوق-الأساسية-للمستهلكين" tabindex="-1">ثانياً: الحقوق الأساسية للمستهلكين <a class="header-anchor" href="#ثانياً-الحقوق-الأساسية-للمستهلكين" aria-label="Permalink to &quot;ثانياً: الحقوق الأساسية للمستهلكين&quot;">​</a></h2><p>يحدد هذا القانون تمتع المستهلكين بالحقوق الأساسية التسعة التالية:</p><table tabindex="0"><thead><tr><th>الحق</th><th>المضمون</th></tr></thead><tbody><tr><td>حق ضمان السلامة</td><td>للمستهلك الحق في عدم تعرض سلامته الشخصية وممتلكاته للأضرار عند شراء السلع واستخدامها وتلقي الخدمات</td></tr><tr><td>حق معرفة الحقيقة</td><td>للمستهلك الحق في معرفة الوضع الحقيقي للسلع المشتراة أو المستخدمة أو الخدمات المتلقاة، بما في ذلك المكونات والفعالية والمخاطر وغيرها</td></tr><tr><td>حق الاختيار المستقل</td><td>للمستهلك الحق في اختيار السلع أو الخدمات بحرية، والمقارنة والتمييز والانتقاء، ورفض المعاملات القسرية</td></tr><tr><td>حق المعاملة العادلة</td><td>للمستهلك الحق في الحصول على شروط معاملة عادلة كضمان الجودة والأسعار المعقولة والقياس الصحيح</td></tr><tr><td>حق المطالبة بالتعويض القانوني</td><td>للمستهلك الذي يتعرض لضرر شخصي أو مادي بسبب شراء أو استخدام السلع أو تلقي الخدمات الحق في الحصول على تعويض وفقاً للقانون</td></tr><tr><td>حق التنظيم للدفاع عن الحقوق</td><td>للمستهلك الحق في تأسيس أو الانضمام إلى منظمات المستهلكين وفقاً للقانون لحماية حقوقه ومصالحه المشروعة</td></tr><tr><td>حق الحصول على المعرفة</td><td>للمستهلك الحق في الحصول على المعرفة والمعلومات المتعلقة بالاستهلاك وحماية حقوق المستهلك</td></tr><tr><td>حق الاحترام</td><td>عند شراء السلع واستخدامها وتلقي الخدمات، يتمتع المستهلك بحق احترام كرامته الشخصية وعاداته القومية</td></tr><tr><td>حق الرقابة</td><td>للمستهلك الحق في الرقابة على السلع والخدمات وأعمال حماية حقوق المستهلك، وتقديم الانتقادات والاقتراحات</td></tr></tbody></table><h2 id="ثالثاً-التزامات-المشغلين" tabindex="-1">ثالثاً: التزامات المشغلين <a class="header-anchor" href="#ثالثاً-التزامات-المشغلين" aria-label="Permalink to &quot;ثالثاً: التزامات المشغلين&quot;">​</a></h2><p>عند تقديم السلع أو الخدمات للمستهلكين، يجب على المشغلين الوفاء بالالتزامات التالية:</p><ol><li><strong>التزام التشغيل القانوني</strong>: يجب على المشغلين الالتزام بالدستور والقوانين ومزاولة الأنشطة التجارية ضمن نطاقهم المرخص.</li><li><strong>التزام ضمان السلامة</strong>: يجب على المشغلين ضمان مطابقة السلع أو الخدمات المقدمة لمتطلبات حماية السلامة الشخصية والممتلكات، وتقديم إيضاحات صادقة وتحذيرات واضحة للسلع والخدمات التي قد تشكل خطراً على السلامة.</li><li><strong>التزام المعلومة الصادقة</strong>: يجب على المشغلين تقديم معلومات صادقة عن السلع أو الخدمات للمستهلكين، وعدم القيام بإعلانات كاذبة أو مضللة. ويجب على السلع والخدمات الزراعية الإشارة بصدق إلى حدود الفعالية والمخاطر المحتملة.</li><li><strong>التزام ضمان الجودة</strong>: يجب على المشغلين ضمان أن السلع أو الخدمات المقدمة تتمتع، في ظل الاستخدام العادي للسلع أو تلقي الخدمات، بالجودة والأداء والغرض ومدة الصلاحية الواجبة.</li><li><strong>التزام المعاملة العادلة</strong>: لا يجوز للمشغلين، عبر الشروط النموذجية والإشعارات والتصريحات والإعلانات داخل المحل أو غيرها من الوسائل، وضع أحكام غير عادلة أو غير معقولة تستبعد أو تقيد حقوق المستهلكين، أو تخفف أو تعفي من مسؤولية المشغل، أو تثقل مسؤولية المستهلك.</li><li><strong>التزام خدمة ما بعد البيع</strong>: يجب على المشغلين، وفقاً للوائح الدولة أو الاتفاقات مع المستهلكين، تحمل مسؤولية الإصلاح والاستبدال والإرجاع وغيرها من خدمات ما بعد البيع.</li><li><strong>التزام حماية الخصوصية</strong>: يجب على المشغلين حماية المعلومات الشخصية وبيانات الوعي للمستهلكين؛ وبدون موافقة المستهلك، لا يجوز جمعها أو استخدامها أو إفشاؤها.</li></ol><h2 id="رابعاً-حل-النزاعات-والمسؤولية-القانونية" tabindex="-1">رابعاً: حل النزاعات والمسؤولية القانونية <a class="header-anchor" href="#رابعاً-حل-النزاعات-والمسؤولية-القانونية" aria-label="Permalink to &quot;رابعاً: حل النزاعات والمسؤولية القانونية&quot;">​</a></h2><p>عند نشوء نزاع حول حقوق المستهلك بين المستهلك والمشغل، يمكن حله عبر الطرق التالية:</p><ul><li>التفاوض والتسوية مع المشغل</li><li>طلب الوساطة من منظمة المستهلكين</li><li>تقديم شكوى إلى الجهة الإدارية المختصة</li><li>طلب التحكيم من هيئة التحكيم وفقاً لاتفاق التحكيم المبرم مع المشغل</li><li>رفع دعوى أمام محكمة التكافل</li></ul><p>يتحمل المشغلون المخالفون لأحكام هذا القانون والمعتدون على الحقوق والمصالح المشروعة للمستهلكين المسؤوليات التالية:</p><table tabindex="0"><thead><tr><th>الفعل المخالف</th><th>المسؤولية القانونية</th></tr></thead><tbody><tr><td>تقديم سلع أو خدمات معيبة تسبب ضرراً</td><td>تحمل مسؤولية التعويض، بما في ذلك النفقات الطبية وتعويض تعطل العمل وتعويض الإعاقة وغيرها</td></tr><tr><td>السلوك الاحتيالي</td><td>زيادة التعويض بطلب المستهلك، بقيمة ثلاثة أضعاف ثمن السلع المشتراة أو تكلفة الخدمات المتلقاة</td></tr><tr><td>الإعلان الكاذب</td><td>الأمر بوقف الفعل المخالف وإزالة الأثر ودفع غرامة</td></tr><tr><td>المعاملة القسرية</td><td>الأمر بالتصحيح وإرجاع الرسوم غير المعقولة ودفع غرامة</td></tr><tr><td>انتهاك خصوصية المستهلك</td><td>تحمل تعويض الضرر المعنوي، وفي الحالات الجسيمة تطبق المسؤولية الجنائية</td></tr></tbody></table><h2 id="خامساً-منظمات-المستهلكين-والرقابة-الاجتماعية" tabindex="-1">خامساً: منظمات المستهلكين والرقابة الاجتماعية <a class="header-anchor" href="#خامساً-منظمات-المستهلكين-والرقابة-الاجتماعية" aria-label="Permalink to &quot;خامساً: منظمات المستهلكين والرقابة الاجتماعية&quot;">​</a></h2><p>تشجع الدولة وتدعم جميع المنظمات والأفراد في ممارسة الرقابة الاجتماعية على الأفعال التي تضر بالحقوق والمصالح المشروعة للمستهلكين. جمعية المستهلكين منظمة اجتماعية تأسست قانوناً لممارسة الرقابة الاجتماعية على السلع والخدمات وحماية الحقوق والمصالح المشروعة للمستهلكين، وتؤدي الوظائف التالية:</p><ol><li>تقديم معلومات الاستهلاك وخدمات الاستشارة للمستهلكين</li><li>المشاركة في الرقابة والتفتيش على السلع والخدمات من قبل الجهات الإدارية المختصة</li><li>عرض المسائل المتعلقة بالحقوق والمصالح المشروعة للمستهلكين على الجهات الإدارية المختصة والاستفسار وتقديم الاقتراحات</li><li>تلقي شكاوى المستهلكين والتحقيق في موضوعات الشكاوى والوساطة فيها</li><li>دعم المستهلكين المتضررين في رفع الدعاوى ضد الأفعال التي تضر بالحقوق والمصالح المشروعة للمستهلكين</li></ol><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>قانون حماية المستهلك</em> هو الحارس لنظام السوق في حضارة التكافل المرساة. بمنح المستهلكين حقوقاً كاملة، وتقييد سلوك المشغلين، وإنشاء آلية متعددة المسارات لحل النزاعات، يضمن سير معاملات السوق على مسار الإنصاف والصدق والتكافل، ويمنع المجال التجاري من أن يصبح مرتعاً جديداً للسلوكيات الافتراسية.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>41-共生劳动法 (قانون العمل التكافلي)</li><li>47-反垄断法 (قانون مناهضة الاحتكار)</li><li>36-社会结构与阶层流动 (البنية الاجتماعية وتنقل الطبقات)</li></ul>',23)])])}const p=a(e,[["render",i]]);export{_ as __pageData,p as default};
